<script setup lang="ts">
import { uiText } from "../uiText";
import {computed,ref} from 'vue';
import type {MatchDetail,MatchTimeline,TimelineEvent} from '../../bindings/leaguepingo/internal/core/models';
import {clock,teamGold} from '../analysisData';
import {number} from '../presentation';
import mapImage from '../assets/game/analysis/map11.png';
import GameIcon from './GameIcon.vue';
const props=defineProps<{timeline:MatchTimeline;detail:MatchDetail}>();
const time=ref(0),type=ref('all'),player=ref(0);
const maxTime=computed(()=>(props.timeline.frames??[]).at(-1)?.timestamp??0);
const frame=computed(()=>[...(props.timeline.frames??[])].reverse().find(f=>f.timestamp<=time.value)??props.timeline.frames?.[0]);
const players=computed(()=>props.detail.players??[]);
const playerById=(id:number)=>players.value.find(p=>p.participantId===id);
const eventTeam=(e:TimelineEvent)=>playerById(e.killerId||e.participantId)?.teamId??e.teamId;
const eventName=(e:TimelineEvent)=>e.type==='CHAMPION_KILL'?uiText.common.kills:e.type==='BUILDING_KILL'?(e.building==='INHIBITOR_BUILDING'?uiText.matchTimeline.inhibitor:uiText.matchTimeline.building):({DRAGON:uiText.matchTimeline.dragon,HORDE:uiText.matchTimeline.grub,RIFTHERALD:uiText.matchTimeline.herald,RIFT_HERALD:uiText.matchTimeline.herald,BARON_NASHOR:uiText.matchTimeline.baron,ATAKHAN:uiText.matchTimeline.atakhan}[e.monster]??uiText.matchTimeline.epicMonster);
const events=computed(()=>(props.timeline.events??[]).filter(e=>['CHAMPION_KILL','BUILDING_KILL','ELITE_MONSTER_KILL'].includes(e.type)).filter(e=>type.value==='all'||e.type===type.value).filter(e=>!player.value||[e.killerId,e.victimId,e.participantId].includes(player.value)));
const gold=computed(()=>(props.timeline.frames??[]).map(f=>{const blue=teamGold(f,props.detail,100),red=teamGold(f,props.detail,200);return {time:f.timestamp,value:blue!=null&&red!=null?blue-red:null};}));
const goldMax=computed(()=>Math.max(1000,...gold.value.map(p=>Math.abs(p.value??0))));
const x=(t:number)=>maxTime.value?t/maxTime.value*660+45:45;
const y=(v:number)=>80-v/goldMax.value*57;
const goldPoints=computed(()=>{const lines:string[]=[];let line='';for(const p of gold.value){if(p.value==null){if(line)lines.push(line);line='';continue;}line+=`${x(p.time)},${y(p.value)} `;}if(line)lines.push(line);return lines;});
const difference=computed(()=>{if(!frame.value)return null;const a=teamGold(frame.value,props.detail,100),b=teamGold(frame.value,props.detail,200);return a!=null&&b!=null?a-b:null;});
const mapPoint=(p:{x:number;y:number})=>({left:`${Math.max(0,Math.min(100,p.x/15000*100))}%`,top:`${100-Math.max(0,Math.min(100,p.y/15000*100))}%`});
function jump(e:TimelineEvent){time.value=Math.min(maxTime.value,e.timestamp);}
</script>
<template><section class="match-timeline"><header><h3>{{ uiText.matchTimeline.title }}</h3><span v-if="timeline.partial">{{ uiText.matchTimeline.framesHint }}</span><span v-else>{{ uiText.matchTimeline.frames((timeline.frames??[]).length) }}</span></header><div class="timeline-controls"><label>{{ uiText.common.events }}<select v-model="type" :aria-label="uiText.matchTimeline.eventFilter"><option value="all">{{ uiText.matchTimeline.allEvents }}</option><option value="CHAMPION_KILL">{{ uiText.common.kills }}</option><option value="BUILDING_KILL">{{ uiText.matchTimeline.buildings }}</option><option value="ELITE_MONSTER_KILL">{{ uiText.matchTimeline.epicMonster }}</option></select></label><label>{{ uiText.common.player }}<select v-model.number="player" :aria-label="uiText.matchTimeline.playerFilter"><option :value="0">{{ uiText.matchTimeline.allPlayers }}</option><option v-for="p in players" :key="p.participantId" :value="p.participantId">{{p.displayName}}</option></select></label><span>{{ uiText.matchTimeline.eventCount(events.length) }}</span></div><div class="timeline-content"><div class="timeline-map-area"><div v-if="detail.mapId===11" class="timeline-map"><img :src="mapImage" :alt="uiText.matchTimeline.mapLabel"/><span v-for="p in frame?.players?.filter(p=>p.position)" :key="p.participantId" class="map-player" :class="{'team-red':playerById(p.participantId)?.teamId===200,target:playerById(p.participantId)?.target}" :style="mapPoint(p.position!)" :title="uiText.matchTimeline.position(playerById(p.participantId)?.displayName??uiText.common.player, clock(frame?.timestamp??0), number(p.gold))"><GameIcon :id="playerById(p.participantId)?.summary.championId" :size="24"/></span><span v-for="(e,i) in events.filter(e=>e.position&&Math.abs(e.timestamp-time)<30000)" :key="`e-${i}`" class="map-event" :style="mapPoint(e.position!)" :title="`${clock(e.timestamp)} ${eventName(e)}`"/></div><div v-else class="timeline-map-unavailable">{{ uiText.matchTimeline.unsupportedMap }}</div><p>{{ uiText.matchTimeline.sampling(clock(frame?.timestamp??0)) }}</p></div><div class="timeline-events" tabindex="0" :aria-label="uiText.matchTimeline.eventsLabel"><button v-for="(e,i) in events" :key="i" class="timeline-event" :class="{'team-red':eventTeam(e)===200,selected:Math.abs(time-e.timestamp)<1000}" @click="jump(e)"><time>{{clock(e.timestamp)}}</time><GameIcon :id="playerById(e.killerId||e.participantId)?.summary.championId" :size="22"/><span><strong :title="playerById(e.killerId||e.participantId)?.displayName">{{playerById(e.killerId||e.participantId)?.displayName||uiText.matchTimeline.environment}}</strong><small>{{eventName(e)}}<template v-if="e.victimId"> · {{playerById(e.victimId)?.displayName||uiText.common.player}}</template></small></span></button><p v-if="!events.length" class="timeline-empty">{{ uiText.matchTimeline.empty }}</p></div></div><div class="economy-chart"><div><h4>{{ uiText.matchTimeline.goldDifference }}<small>{{ uiText.matchTimeline.differenceLabel }}</small></h4><b :class="difference!=null&&difference<0?'red':'blue'">{{difference==null?'—':`${difference>0?'+':''}${difference.toLocaleString()}`}} <small>{{ uiText.common.gold }}</small></b></div><svg viewBox="0 0 730 170" role="img" :aria-label="uiText.matchTimeline.goldChartLabel"><g v-for="v in [-goldMax,0,goldMax]" :key="v"><line x1="45" x2="705" :y1="y(v)" :y2="y(v)"/><text x="37" :y="y(v)+4" text-anchor="end">{{v===0?'0':`${v>0?'+':''}${(v/1000).toFixed(0)}k`}}</text></g><polyline v-for="(points,i) in goldPoints" :key="i" :points="points"/><line class="time-marker" :x1="x(time)" :x2="x(time)" y1="18" y2="140"/><text x="45" y="162">0:00</text><text x="705" y="162" text-anchor="end">{{clock(maxTime)}}</text></svg><p v-if="gold.every(p=>p.value==null)" class="timeline-empty">{{ uiText.matchTimeline.missingGold }}</p></div><label class="timeline-slider"><span>{{clock(time)}}</span><input v-model.number="time" type="range" min="0" :max="maxTime" step="1000" :aria-label="uiText.matchTimeline.time"/><span>{{clock(maxTime)}}</span></label></section></template>
<style scoped>
/* Scope inside :where and retain original specificity with :is; child boundaries use :deep. */
:where(:is(.timeline-event,.timeline-events):focus-visible):is(:is(.desktop-app,.drawer-floating,.overlay-shell) :is(.match-main,.timeline-event,.detail-table-scroll,.timeline-events):focus-visible) { outline-offset: -3px; }
</style>
<style scoped>
.match-timeline{padding:16px;}.match-timeline>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;}.match-timeline h3{font-size:14px;margin:0;}.match-timeline header>span{font-size:11px;color:var(--muted);}.timeline-controls{display:flex;align-items:center;gap:14px;margin-bottom:12px;}.timeline-controls label{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--muted);}.timeline-controls select{font-size:12px;max-width:190px;}.timeline-controls>span{font-size:11px;color:var(--muted);margin-left:auto;}.timeline-content{display:grid;grid-template-columns:minmax(0,1fr) minmax(220px,.8fr);gap:14px;align-items:start;}.timeline-map-area{min-width:0;}.timeline-map{position:relative;width:100%;aspect-ratio:1;background:var(--raised);overflow:hidden;}.timeline-map>img{width:100%;height:100%;display:block;opacity:.8;filter:saturate(.4) brightness(.85);}.map-player{position:absolute;transform:translate(-50%,-50%);border:2px solid var(--ally);border-radius:4px;display:flex;z-index:1;}.map-player.team-red{border-color:var(--enemy);}.map-player.target{outline:2px solid var(--accent);outline-offset:2px;z-index:2;}.map-event{position:absolute;transform:translate(-50%,-50%);width:12px;height:12px;border:2px solid var(--text);border-radius:50%;background:var(--enemy);pointer-events:none;}.timeline-map-area>p{font-size:11px;color:var(--muted);line-height:1.6;margin:8px 0 0;}.timeline-map-unavailable{aspect-ratio:1;display:grid;place-items:center;background:var(--raised);padding:24px;text-align:center;font-size:12px;color:var(--muted);}.timeline-events{height:340px;overflow:auto;overscroll-behavior:contain;}.timeline-event{width:100%;display:flex;align-items:center;gap:8px;padding:8px 7px;background:color-mix(in srgb,var(--ally) 8%,var(--panel));border:0;border-left:3px solid var(--ally);border-bottom:1px solid var(--border);border-radius:0;text-align:left;min-height:48px;}.timeline-event.team-red{border-left-color:var(--enemy);background:color-mix(in srgb,var(--enemy) 8%,var(--panel));}.timeline-event.selected{outline:1px solid var(--accent);outline-offset:-1px;}.timeline-event time{font-size:11px;color:var(--muted);width:33px;flex:none;}.timeline-event>span{min-width:0;}.timeline-event strong{font-size:12px;font-weight:500;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}.timeline-event small{display:block;font-size:11px;color:var(--muted);margin-top:4px;overflow-wrap:anywhere;}.economy-chart{margin-top:18px;}.economy-chart>div{display:flex;align-items:center;justify-content:space-between;}.economy-chart h4{margin:0;font-size:12px;}.economy-chart h4 small,.economy-chart b small{font-size:11px;color:var(--muted);font-weight:400;margin-left:6px;}.economy-chart b{font-size:16px;font-variant-numeric:tabular-nums;}.blue{color:var(--ally);}.red{color:var(--enemy);}.economy-chart svg{width:100%;height:auto;max-height:190px;display:block;}.economy-chart line{stroke:var(--border);stroke-width:1;}.economy-chart text{fill:var(--muted);font-size:11px;}.economy-chart polyline{fill:none;stroke:var(--ally);stroke-width:2;}.economy-chart .time-marker{stroke:var(--accent);stroke-dasharray:3 3;}.timeline-slider{display:flex;gap:12px;align-items:center;font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums;margin-top:6px;}.timeline-slider input{flex:1;min-width:0;accent-color:var(--accent);}.timeline-empty{font-size:12px;color:var(--muted);padding:12px;line-height:1.6;}@container(max-width:590px){.timeline-content{grid-template-columns:minmax(0,1fr) minmax(180px,.9fr);gap:10px;}.timeline-events{height:250px;}.timeline-event{gap:5px;padding:6px 5px;}.timeline-event time{width:28px;}.timeline-controls{gap:8px;}.timeline-controls select{max-width:135px;}}
</style>
